-- Price-text corrections from the 2026-10-15 commerce audit (mirror of src/data/commercePriceFixes.js).
-- Each update applies only while the row still has the audited old text. Apply after commerce_engine.sql.
begin;
update public.product_catalog set price = '$33.30 (10 suppositories)', updated_at = now() where id = 'p-neycher-odor-be-gone' and price = '$29.97 (10 suppositories)';
insert into public.commerce_audit_log(product_id, provider, old_status, new_status, issues, severity, price_changed, check_source, automatic, notes) select 'p-neycher-odor-be-gone', null, 'PRICE_MISMATCH', 'CORRECTED', '{PRICE_MISMATCH}', 'MEDIUM', true, 'catalog_audit_2026-10-15', false, '$29.97 (10 suppositories) -> $33.30 (10 suppositories): helloneycher.com/product/odor-be-gone: one-time $33.30; $29.97 is the monthly subscription price' where exists (select 1 from public.product_catalog where id = 'p-neycher-odor-be-gone');
