-- Restore Neycher partner tracking links missing from the live rows (present in src/data/brands.js).
update public.product_catalog set extra = jsonb_set(extra, '{affiliateUrl}', to_jsonb('https://helloneycher.com/product/vaginal-moisturizer?sca_ref=12276038.vwBYOKCYa7&utm_source=affiliate&utm_medium=socialmedia&utm_campaign=affiliate'::text)), updated_at = now() where id = 'p-neycher-vaginal-moisturizer' and coalesce(extra->>'affiliateUrl','') = '';
